from solution import filter_integers
import copy
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(values):
    # Obviously-correct model: keep values whose exact logical type is integer,
    # excluding booleans (bool is a subclass of int but is not an integer value).
    return [v for v in values if isinstance(v, int) and not isinstance(v, bool)]


def test_examples_first():
    assert filter_integers(['a', 3.14, 5]) == [5]


def test_examples_second():
    assert filter_integers([1, 2, 3, 'abc', {}, []]) == [1, 2, 3]


def test_booleans_excluded():
    assert filter_integers([True, False, 1, 2]) == [1, 2]


def test_booleans_only_gives_empty():
    assert filter_integers([True, False]) == []


def test_true_is_not_one():
    # True == 1 but must not be kept
    result = filter_integers([True])
    assert result == []
    assert result != [1] or result == []


def test_false_is_not_zero():
    result = filter_integers([False])
    assert result == []
    assert 0 not in result


def test_empty_list():
    assert filter_integers([]) == []


def test_integral_floats_excluded():
    assert filter_integers([3.0, 2.0, 1, 0]) == [1, 0]
    assert filter_integers([float(5)]) == []


def test_numeric_strings_excluded():
    assert filter_integers(['1', '0', '-5', 5]) == [5]


def test_none_and_containers_excluded():
    assert filter_integers([None, {}, [], (), set(), 7]) == [7]


def test_negative_zero_and_large_ints():
    vals = [-10**100, -1, 0, 1, 10**100]
    assert filter_integers(vals) == vals


def test_order_preserved_and_length_bound():
    vals = [5, 'a', 3, 3.14, -2, None, 0]
    assert filter_integers(vals) == [5, 3, -2, 0]


def test_returns_list_type():
    r = filter_integers([1, 'a'])
    assert isinstance(r, list)
    assert r == [1]


def test_does_not_mutate_input():
    vals = [1, 'a', True, 3.14, 2]
    snapshot = copy.deepcopy(vals)
    filter_integers(vals)
    assert vals == snapshot


@given(st.lists(st.integers(min_value=-1000, max_value=1000), max_size=20))
def test_all_integers_identity(xs):
    assert filter_integers(xs) == xs


@given(st.lists(st.one_of(
    st.integers(min_value=-100, max_value=100),
    st.booleans(),
    st.floats(allow_nan=False, allow_infinity=False, width=32),
    st.text(max_size=5),
    st.none(),
), max_size=30))
def test_reference_model_equivalence(vals):
    assert filter_integers(vals) == reference(vals)


@given(st.lists(st.booleans(), min_size=1, max_size=20))
def test_bool_lists_always_empty(bools):
    assert filter_integers(bools) == []


@given(st.lists(st.one_of(
    st.integers(min_value=-50, max_value=50),
    st.just(True),
    st.just(False),
    st.just(3.0),
    st.just("5"),
    st.just(None),
), max_size=30))
def test_no_bool_no_float_no_str_in_output(vals):
    out = filter_integers(vals)
    for v in out:
        assert isinstance(v, int) and not isinstance(v, bool)
    # every kept element came from input in order
    assert len(out) <= len(vals)
    # output is subsequence of input preserving order
    it = iter(vals)
    for kept in out:
        for cand in it:
            if cand is kept or (type(cand) is int and cand == kept):
                break
        else:
            assert False, "output not a subsequence of input"


@given(st.lists(st.integers(min_value=-100, max_value=100), max_size=10),
       st.lists(st.text(max_size=3), max_size=10))
def test_mixed_ints_and_nonints(ints, strs):
    mixed = ints + strs
    assert filter_integers(mixed) == reference(mixed)
